.wb-para{font-size:14.5px;line-height:1.55;font-weight:500;color:#1a1a1a;margin:0;}
.wb-body{flex:1;display:flex;flex-direction:column;gap:9px;}
.wb-chiplist{display:flex;flex-wrap:wrap;gap:8px;}
.wb-chip{background:#1D4ED814;border:1.5px solid #1D4ED855;color:#1a1a1a;
 font-weight:700;font-size:13.5px;padding:6px 12px;border-radius:9px;}
.wb-table{border-collapse:collapse;font-size:14px;width:100%;}
.wb-table td{padding:6px 8px;border-bottom:1px solid #E5E7EB;vertical-align:top;}
.wb-word{font-weight:800;color:#1D4ED8;white-space:nowrap;}
.wb-bullets{margin:0;padding-left:20px;font-size:14px;line-height:1.6;}
.wb-bullets li{margin-bottom:3px;}
.wb-hint{font-size:12.5px;color:#6B7280;font-style:italic;}
.wb-fullline{width:100%;border-bottom:2px solid #9CA3AF;height:22px;box-sizing:border-box;}

.wb-shell{box-sizing:border-box;padding:0 0 20px;min-height:100%;display:flex;
 flex-direction:column;gap:10px;font-family:'Poppins','Segoe UI',Arial,sans-serif;
 color:#1a1a1a;background:#ffffff;}
